#!/usr/bin/env python3
# AI DISCLAIMER: All of the text in this file was generated by AI.
"""Wallet-speed task driver: build FCMP++ txs with n inputs on monerodato.2's wallet-rpc, never relayed.
Freezes every output, then per run thaws exactly n split-wave outputs and calls sweep_all(do_not_relay=True) to the
wallet's own address. Records RPC wall time and the wallet process's CPU time (utime+stime) over the call.
usage: wprof_drive.py <wallet-rpc pid> <out csv> <n,n,...> <rounds> [prep]"""
import json, os, sys, time, urllib.request
URL = "http://127.0.0.1:%s/json_rpc" % os.environ.get("WPORT", "28483")
WAVE_AMOUNT = 37499954878  # the 16-way split outputs of 2026-11-06 (0.0375 each)
def rpc(method, params=None, timeout=3600):
    req = urllib.request.Request(URL, data=json.dumps({"jsonrpc": "2.0", "id": 0, "method": method, "params": params or {}}).encode(),
                                 headers={"Content-Type": "application/json"})
    r = json.loads(urllib.request.urlopen(req, timeout=timeout).read())
    if "error" in r: raise RuntimeError(f"{method}: {r['error']}")
    return r["result"]
def cpu_s(pid):
    f = open(f"/proc/{pid}/stat").read().rsplit(")", 1)[1].split()
    return (int(f[11]) + int(f[12])) / os.sysconf("SC_CLK_TCK")
def main():
    pid, out, ns, rounds = int(sys.argv[1]), sys.argv[2], [int(x) for x in sys.argv[3].split(",")], int(sys.argv[4])
    prep = len(sys.argv) > 5 and sys.argv[5] == "prep"
    rpc("open_wallet", {"filename": os.environ.get("WNAME", "w006"), "password": ""}, timeout=600)
    rpc("refresh", {}, timeout=1200)
    h = rpc("get_height")["height"]
    tr = rpc("incoming_transfers", {"transfer_type": "available", "account_index": 0}).get("transfers", [])
    wave = sorted([t for t in tr if t["amount"] == WAVE_AMOUNT and not t.get("frozen") and t.get("unlocked", True)],
                  key=lambda t: t["global_index"])
    print(f"wallet height {h}; available {len(tr)}; split-wave outputs {len(wave)}", flush=True)
    if prep:
        for t in tr:
            if not t.get("frozen"): rpc("freeze", {"key_image": t["key_image"]})
        rpc("store", {})
        print(f"froze {len(tr)} outputs", flush=True)
    addr = rpc("get_address", {"account_index": 0})["address"]
    need = max(ns)
    pool = sorted([t for t in rpc("incoming_transfers", {"transfer_type": "available", "account_index": 0})["transfers"]
                   if t["amount"] == WAVE_AMOUNT], key=lambda t: t["global_index"])[:need]
    assert len(pool) == need, f"only {len(pool)} split-wave outputs"
    new = not os.path.exists(out)
    with open(out, "a") as f:
        if new: f.write("utc,round,n_inputs,wall_s,cpu_s,cpu_per_wall,n_txs,fee,weight,tx_size_bytes\n")
        for r in range(1, rounds + 1):
            order = ns if r % 2 else list(reversed(ns))
            for n in order:
                for t in pool[:n]: rpc("thaw", {"key_image": t["key_image"]})
                c0, t0 = cpu_s(pid), time.time()
                res = rpc("sweep_all", {"address": addr, "account_index": 0, "do_not_relay": True, "get_tx_hex": True,
                                        "priority": 0, "below_amount": WAVE_AMOUNT + 1})
                t1, c1 = time.time(), cpu_s(pid)
                for t in pool[:n]: rpc("freeze", {"key_image": t["key_image"]})
                ntx = len(res.get("tx_hash_list", []))
                fee = sum(res.get("fee_list", [0])); w = sum(res.get("weight_list", [0]))
                sz = sum(len(x) // 2 for x in res.get("tx_blob_list", []))
                line = f"{time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime(t0))},{r},{n},{t1 - t0:.2f},{c1 - c0:.2f},{(c1 - c0) / (t1 - t0):.2f},{ntx},{fee},{w},{sz}"
                f.write(line + "\n"); f.flush(); print(line, flush=True)
    rpc("store", {})
main()
